'use client'

import {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from 'react'
import { useReducedMotion } from 'motion/react'
import {
  FOOTER_SOCIALS,
  FooterSocialLinks,
  type FooterSocialItem,
} from '@/components/blocks/footer/footer'
import { cn } from '@/lib/utils'

const DASH = 420

function Signature({
  text,
  label,
  fontFamily,
}: {
  text: string
  label: string
  fontFamily: string
}) {
  const ref = useRef<SVGSVGElement>(null)
  const reduceMotion = useReducedMotion()
  const [inView, setInView] = useState(false)
  const drawn = Boolean(reduceMotion) || inView

  useEffect(() => {
    const node = ref.current
    if (!node || reduceMotion) return
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return
        setInView(true)
        observer.disconnect()
      },
      { threshold: 0.6 },
    )
    observer.observe(node)
    return () => observer.disconnect()
  }, [reduceMotion])

  return (
    <svg ref={ref} role="img" aria-label={label} viewBox="0 0 240 72" className="h-14 w-auto">
      <text
        x="120"
        y="50"
        textAnchor="middle"
        fontSize="48"
        strokeWidth="0.9"
        strokeDasharray={DASH}
        style={{
          fontFamily,
          strokeDashoffset: drawn ? 0 : DASH,
          fillOpacity: drawn ? 1 : 0,
          transition: reduceMotion
            ? 'none'
            : 'stroke-dashoffset var(--motion-dur-ambient) var(--motion-ease-in-out), fill-opacity var(--motion-dur-showcase) var(--motion-ease-out) var(--motion-dur-ambient)',
        }}
        className="fill-current stroke-current"
      >
        {text}
      </text>
    </svg>
  )
}

export interface FooterSignatureProps extends ComponentPropsWithoutRef<'footer'> {
  signature?: string
  signatureLabel?: string
  signatureFont?: string
  socials?: FooterSocialItem[]
  copyright?: ReactNode
}

export const FooterSignature = forwardRef<HTMLElement, FooterSignatureProps>(
  (
    {
      signature = 'Nexvyn',
      signatureLabel = 'Signed, Nexvyn',
      signatureFont = 'var(--font-handwriting), cursive',
      socials = FOOTER_SOCIALS,
      copyright = '© 2026 Nexvyn',
      className,
      ...props
    },
    ref,
  ) => (
    <footer
      ref={ref}
      className={cn('w-full border-t border-(--color-border) bg-(--color-bg)', className)}
      {...props}
    >
      <div className="mx-auto flex max-w-5xl flex-col items-center gap-4 px-6 py-6 sm:px-8 md:grid md:grid-cols-[1fr_auto_1fr] md:gap-8">
        <div className="text-(--color-fg) md:order-2">
          <Signature text={signature} label={signatureLabel} fontFamily={signatureFont} />
        </div>
        <div className="flex w-full items-center justify-between md:contents">
          {copyright && (
            <p className="text-xs leading-5 text-(--color-muted) md:order-1">{copyright}</p>
          )}
          <FooterSocialLinks items={socials} className="-me-3 md:order-3 md:justify-self-end" />
        </div>
      </div>
    </footer>
  ),
)
FooterSignature.displayName = 'FooterSignature'

'use client'

import { forwardRef, type ComponentPropsWithoutRef, type ReactNode } from 'react'
import { Slot } from '@radix-ui/react-slot'
import { HugeiconsIcon } from '@hugeicons/react'
import { GithubIcon, NewTwitterIcon } from '@hugeicons/core-free-icons'
import { cn } from '@/lib/utils'

export type FooterLinkItem = { label: string; href: string }
export type FooterColumnItem = { title: string; links: FooterLinkItem[] }
export type FooterSocialItem = { label: string; href: string; icon: ReactNode }

export const FOOTER_SOCIALS: FooterSocialItem[] = [
  {
    label: 'GitHub',
    href: '#',
    icon: <HugeiconsIcon icon={GithubIcon} size={18} strokeWidth={1.5} />,
  },
  {
    label: 'X',
    href: '#',
    icon: <HugeiconsIcon icon={NewTwitterIcon} size={18} strokeWidth={1.5} />,
  },
]

export interface FooterLinkProps extends ComponentPropsWithoutRef<'a'> {
  asChild?: boolean
}

export const FooterLink = forwardRef<HTMLAnchorElement, FooterLinkProps>(
  ({ asChild, className, ...props }, ref) => {
    const Comp = asChild ? Slot : 'a'

    return (
      <Comp
        ref={ref}
        className={cn(
          'inline-flex items-center rounded-md text-sm text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:text-(--color-fg) focus-visible:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none [@media(hover:none)]:min-h-11',
          className,
        )}
        {...props}
      />
    )
  },
)
FooterLink.displayName = 'FooterLink'

export function FooterSocialLinks({
  items,
  className,
}: {
  items: FooterSocialItem[]
  className?: string
}) {
  if (items.length === 0) return null

  return (
    <ul className={cn('flex items-center gap-1', className)}>
      {items.map((item) => (
        <li key={item.label}>
          <a
            href={item.href}
            aria-label={item.label}
            className="flex size-11 items-center justify-center rounded-md text-(--color-muted) transition-colors duration-(--motion-dur-fast) ease hover:bg-(--color-fg)/5 hover:text-(--color-fg) focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-(--color-accent) motion-reduce:transition-none"
          >
            <span aria-hidden="true" className="inline-flex">
              {item.icon}
            </span>
          </a>
        </li>
      ))}
    </ul>
  )
}

export function FooterColumn({ title, links }: FooterColumnItem) {
  return (
    <div>
      <h2 className="text-sm leading-6 text-(--color-fg)">{title}</h2>
      <ul className="mt-3 flex flex-col gap-2">
        {links.map((link) => (
          <li key={link.label}>
            <FooterLink href={link.href}>{link.label}</FooterLink>
          </li>
        ))}
      </ul>
    </div>
  )
}

export function FooterBrand({ children = 'Nexvyn UI' }: { children?: ReactNode }) {
  return <span className="text-base leading-6 text-(--color-fg)">{children}</span>
}

export const FOOTER_SITEMAP: FooterColumnItem[] = [
  {
    title: 'Library',
    links: [
      { label: 'Components', href: '#' },
      { label: 'Blocks', href: '#' },
      { label: 'Illustrations', href: '#' },
      { label: 'Changelog', href: '#' },
    ],
  },
  {
    title: 'Guides',
    links: [
      { label: 'Installation', href: '#' },
      { label: 'Theming', href: '#' },
      { label: 'MCP setup', href: '#' },
    ],
  },
  {
    title: 'Project',
    links: [
      { label: 'GitHub', href: '#' },
      { label: 'Feedback', href: '#' },
      { label: 'Design language', href: '#' },
    ],
  },
  {
    title: 'Legal',
    links: [
      { label: 'License', href: '#' },
      { label: 'Privacy', href: '#' },
      { label: 'Terms', href: '#' },
    ],
  },
]

export const FOOTER_LEGAL: FooterLinkItem[] = [
  { label: 'Privacy', href: '#' },
  { label: 'Terms', href: '#' },
]

export function FooterSitemap({
  columns,
  className,
}: {
  columns: FooterColumnItem[]
  className?: string
}) {
  return (
    <div className={cn('grid grid-cols-2 gap-x-8 gap-y-10 sm:grid-cols-4', className)}>
      {columns.map((column) => (
        <FooterColumn key={column.title} {...column} />
      ))}
    </div>
  )
}

export function FooterBottomBar({
  copyright,
  links,
  label = 'Legal',
  className,
}: {
  copyright?: ReactNode
  links: FooterLinkItem[]
  label?: string
  className?: string
}) {
  return (
    <div
      className={cn(
        'flex flex-col gap-3 border-t border-(--color-border) py-6 sm:flex-row sm:items-center sm:justify-between',
        className,
      )}
    >
      {copyright && <p className="text-xs leading-5 text-(--color-muted)">{copyright}</p>}
      {links.length > 0 && (
        <nav aria-label={label}>
          <ul className="flex items-center gap-6">
            {links.map((link) => (
              <li key={link.label}>
                <FooterLink href={link.href} className="text-xs">
                  {link.label}
                </FooterLink>
              </li>
            ))}
          </ul>
        </nav>
      )}
    </div>
  )
}
